import re, collections

def parse_grid_text(txt):
    return [[int(x) for x in line.split()] for line in txt.strip().splitlines()]
def get_pair(txt):
    m=re.search(r'Demo pair 1 input \((\d+)x(\d+)\):\n(.*?)\nDemo pair 1 output \((\d+)x(\d+)\):\n(.*?)(?:\n\nSame instance|\nWrong attempts)',txt,re.S)
    if not m: raise ValueError('no match')
    return parse_grid_text(m.group(3)),parse_grid_text(m.group(5))
